BEGIN;
CREATE TEMP TABLE staging_competitor_codes (sku text PRIMARY KEY, codes jsonb) ON COMMIT DROP;

UPDATE elimfilters_catalog t
SET competitor_codes = merged.new_codes
FROM (
  SELECT s.sku,
         (SELECT jsonb_agg(elem)
          FROM (
            SELECT DISTINCT ON (elem->>'manufacturer', elem->>'code') elem
            FROM (
              SELECT jsonb_array_elements(COALESCE(c.competitor_codes, '[]'::jsonb)) AS elem
              UNION ALL
              SELECT jsonb_array_elements(s.codes) AS elem
            ) all_elems
          ) dedup
         ) AS new_codes
  FROM staging_competitor_codes s
  JOIN elimfilters_catalog c ON c.sku = s.sku
) merged
WHERE t.sku = merged.sku;

COMMIT;